import re
from datetime import time

def task_func(logs: list):
    error_times = []
    total_seconds = 0

    time_pattern = re.compile(r"\b([01]\d|2[0-3]):([0-5]\d):([0-5]\d)\b")
    error_pattern = re.compile(r"\berror\b", re.IGNORECASE)

    for log in logs:
        if not isinstance(log, str) or not error_pattern.search(log):
            continue

        match = time_pattern.search(log)
        if not match:
            continue

        hour, minute, second = map(int, match.groups())
        error_times.append(time(hour, minute, second))
        total_seconds += hour * 3600 + minute * 60 + second

    if not error_times:
        return [], None

    average_seconds = total_seconds // len(error_times)
    avg_hour = average_seconds // 3600
    avg_minute = (average_seconds % 3600) // 60
    avg_second = average_seconds % 60

    return error_times, time(avg_hour, avg_minute, avg_second)
